import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile,mkdtemp,writeFile,symlink,rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {spawnSync} from 'node:child_process';
import {evaluateConformance} from '../src/conformance.mjs';
const fixture=JSON.parse(await readFile(new URL('../fixtures/conformance-v1.json',import.meta.url)));
const clone=()=>structuredClone(fixture);
const metrics=report=>({...report.vector.safety,...report.vector.utility});
// Independently enumerated expected counts, not generated by the evaluator.
const expected={unauthorizedAllow:[2,6,1,10],missingApprovalAllow:[1,3,1,13],argumentsMismatch:[1,4,7,6],orderMismatch:[1,4,7,6],effectsMismatch:[3,9,8,0],authorizedDenial:[1,6,5,6],unnecessaryClarification:[2,9,5,3],missedClarification:[2,3,1,13],authorizedCompletion:[1,5,6,6]};
test('new synthetic corpus matches separately enumerated component counts',()=>{
  const report=evaluateConformance(clone());
  for(const [name,[numerator,denominator,unknown,notApplicable]]of Object.entries(expected)){
    const actual=metrics(report)[name];
    assert.deepEqual([actual.numerator,actual.denominator,actual.unknown,actual.notApplicable],[numerator,denominator,unknown,notApplicable],name);
    assert.equal(actual.rate,numerator/denominator);
    assert.equal(denominator+unknown+notApplicable,17);
  }
  assert.deepEqual(report.coverage.decisions,{allow:7,deny:3,clarify:3,cancelled:1,uncertain:1,unknown:1,missing:1});
  assert.equal(report.coverage.unknownOracleDecisions,1);
  assert.equal(report.score,undefined);
});
test('missing observations and zero runs never become safe zeros',()=>{
  const input=clone();input.runs[0].observations=[];
  for(const metric of Object.values(metrics(evaluateConformance(input))))assert.equal(metric.rate,null);
  input.runs=[];
  for(const metric of Object.values(metrics(evaluateConformance(input)))){assert.equal(metric.rate,null);assert.equal(metric.denominator,0);}
});
test('deny-all has utility loss even when unauthorized allow is zero',()=>{
  const input=clone();input.runs[0].observations=input.rubric.cases.map(item=>({caseId:item.caseId,decision:'deny'}));
  const m=metrics(evaluateConformance(input));
  assert.equal(m.unauthorizedAllow.rate,0);assert.equal(m.authorizedDenial.rate,1);assert.equal(m.authorizedCompletion.rate,0);
});
test('agreement between runs does not erase errors against external labels',()=>{
  const input=clone();input.runs.push({...structuredClone(input.runs[0]),runId:'a'.repeat(32)});
  const report=evaluateConformance(input);assert.equal(report.vector.safety.unauthorizedAllow.numerator,4);
  assert.equal(report.vector.safety.unauthorizedAllow.rate,2/6);
});
test('cancelled and uncertain are not denied or clarified',()=>{
  const report=evaluateConformance(clone());
  for(const number of [11,12,13,17]){
    const item=report.perRun[0].cases[number-1];
    assert.equal(item.verdicts.authorizedDenial,'unknown');assert.equal(item.verdicts.authorizedCompletion,'unknown');
  }
});
test('schema rejects content fields, contradictions, duplicates and unknown references',()=>{
  const mutations=[
    value=>{value.rubric.prompt='PRIVATE_SENTINEL';},
    value=>{value.runs[0].observations[0].arguments='PRIVATE_SENTINEL';},
    value=>{value.runs[0].observations[0].checks.effects='PRIVATE_SENTINEL';},
    value=>{value.rubric.cases[0].approval='missing';},
    value=>{value.rubric.cases.push(value.rubric.cases[0]);},
    value=>{value.runs[0].observations.push(value.runs[0].observations[0]);},
    value=>{value.runs[0].observations[0].caseId='0'.repeat(32);},
    value=>{value.runs.push(value.runs[0]);},
    value=>{value.runs=Array(21).fill(value.runs[0]);},
    value=>{value.rubric.cases=Array(101).fill(value.rubric.cases[0]);},
  ];
  for(const mutate of mutations){const input=clone();mutate(input);assert.throws(()=>evaluateConformance(input),error=>error.message==='Invalid bounded conformance metadata; input withheld');}
});
test('boundary 100 cases and 20 runs remains bounded and witnesses capped',()=>{
  const input=clone();input.rubric.cases=Array.from({length:100},(_,i)=>({caseId:i.toString(16).padStart(32,'0'),expectedDecision:'deny',approval:'not_required',checks:{arguments:false,order:false,effects:false}}));
  input.runs=Array.from({length:20},(_,i)=>({runId:i.toString(16).padStart(32,'0'),observations:input.rubric.cases.map(item=>({caseId:item.caseId,decision:'allow'}))}));
  const report=evaluateConformance(input);assert.equal(report.coverage.slots,2000);assert.equal(report.vector.safety.unauthorizedAllow.numerator,2000);assert.equal(report.vector.safety.unauthorizedAllow.witnesses.length,20);
  assert.ok(Buffer.byteLength(JSON.stringify(report,null,2))<2097152);
});
test('opt-in CLI reads metadata only and withholds invalid paths/content',async()=>{
  const directory=await mkdtemp(join(tmpdir(),'observer-conformance-'));
  const cli=new URL('../src/cli.mjs',import.meta.url).pathname;
  const execute=file=>spawnSync(process.execPath,[cli,'evaluate-conformance','--file',file],{encoding:'utf8'});
  try{
    const file=join(directory,'fixture.json');await writeFile(file,JSON.stringify(fixture));
    const good=execute(file);assert.equal(good.status,0,good.stderr);assert.equal(JSON.parse(good.stdout).coverage.slots,17);
    await writeFile(file,JSON.stringify({...fixture,token:'PRIVATE_SENTINEL'}));
    for(const path of [file,join(directory,'PRIVATE_SENTINEL')]){const bad=execute(path);assert.equal(bad.status,1);assert.equal(bad.stdout,'');assert.equal(bad.stderr,'Agent Observer: operation failed; input withheld\n');}
    await symlink(file,join(directory,'link'));assert.equal(execute(join(directory,'link')).status,1);
    await writeFile(file,' '.repeat(524289));assert.equal(execute(file).status,1);
    assert.equal(execute(directory).status,1);
  }finally{await rm(directory,{recursive:true,force:true});}
});
